// 목감고등학교 (경기 시흥시) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by scripts/campuses/mokgam/build-package.mjs
// from OSM way/996955083 + AWS Terrain Tiles: every school building destructible (grammar models, floors estimated where OSM has none),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, MOKGAM_PLACEMENTS, MOKGAM_BUILDING_BASE, MOKGAM_HEIGHT_GRIDS, MOKGAM_HEIGHT_RANGE_M, MOKGAM_ENV_IDS, MOKGAM_DISPLAY, MOKGAM_START_FRAME, MOKGAM_OVERVIEW_AZIMUTH, MOKGAM_CAMERA, MOKGAM_PROVENANCE } from './data.js';
import { MOKGAM_FOOTPRINTS } from './footprints.js';
import { MOKGAM_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(MOKGAM_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/mokgam/${file}`, import.meta.url).href;
const HAZE = MOKGAM_DISPLAY.haze, FADE = MOKGAM_DISPLAY.fade;

export const MOKGAM = Object.freeze({
  id: 'mokgam',
  meta: Object.freeze({ school: '목감고등학교', campus: '경기 시흥시', short: '목감고', modelNoun: '목감고' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: MOKGAM_PLACEMENTS,
  approvedCount: MOKGAM_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/campuses/mokgam/build-package.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600
    ? { min: [-25, -9, -23], max: [-7, 1, -17], azimuth: 2.8, elevationDegrees: 22 }
    : { min: [-28, -7, -25], max: [4, 3, -10], azimuth: 3.05, elevationDegrees: 20 }; }, overviewAzimuth: MOKGAM_OVERVIEW_AZIMUTH }),
  camera: MOKGAM_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: MOKGAM_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: MOKGAM_HEIGHT_GRIDS, buildingBase: MOKGAM_BUILDING_BASE, source: MOKGAM_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: MOKGAM_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: MOKGAM_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'scripts/campuses/mokgam/build-package.mjs baked ground' }),
  }),
  protected: Object.freeze({ models: MOKGAM_PROTECTED }),
  hazardTape: Object.freeze({ footprints: MOKGAM_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: MOKGAM_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default MOKGAM;
